package com.example.library;
import com.example.library.entity.*;import com.example.library.dto.*;import com.example.library.repository.*;import com.example.library.service.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import org.springframework.security.test.context.support.WithMockUser;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.MediaType;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:rubric_test;DB_CLOSE_DELAY=-1","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.database-platform=org.hibernate.dialect.H2Dialect","spring.jpa.hibernate.ddl-auto=create-drop","app.seed.enabled=false"}) @AutoConfigureMockMvc @Transactional
class RubricIntegrationTest {
 @Autowired MockMvc mvc;@Autowired BookService service;@Autowired BookRepository books;@Autowired BookCopyRepository copies;@Autowired CopyEventRepository events;@Autowired CategoryRepository categories;@Autowired AuthorRepository authors;@Autowired PublisherRepository publishers;@Autowired UserRepository users;@Autowired FavoriteRepository favorites;
 BookCreateRequest request(){var r=new BookCreateRequest();r.setTitle("Rubric book");r.setTotalQuantity(2);r.setRentalPrice(BigDecimal.valueOf(5000));r.setSalePrice(BigDecimal.valueOf(50000));return r;}
 @Test @WithMockUser(roles="ADMIN") void newBookCanBeCreatedUpdatedAndDeletedWithUnusedCopies()throws Exception{var book=service.createBook(request());assertEquals(2,copies.countByBookId(book.getId()));var r=request();r.setTitle("Updated");service.updateBook(book.getId(),r);assertEquals("Updated",books.findById(book.getId()).orElseThrow().getTitle());mvc.perform(delete("/api/v1/books/"+book.getId())).andExpect(status().isNoContent());assertFalse(books.existsById(book.getId()));assertEquals(0,copies.countByBookId(book.getId()));assertEquals(0,events.count());}
 @Test @WithMockUser(roles="ADMIN") void allThreeTaxonomiesBlockDeletionWhileBooksReferenceThem()throws Exception{var c=categories.save(Category.builder().name("Category").build());var a=authors.save(Author.builder().name("Author").build());var p=publishers.save(Publisher.builder().name("Publisher").build());var r=request();r.setCategoryId(c.getId());r.setAuthorId(a.getId());r.setPublisherId(p.getId());var book=service.createBook(r);for(var pair:java.util.Map.of("categories",c.getId(),"authors",a.getId(),"publishers",p.getId()).entrySet())mvc.perform(delete("/api/v1/"+pair.getKey()+"/"+pair.getValue())).andExpect(status().isConflict());mvc.perform(delete("/api/v1/books/"+book.getId())).andExpect(status().isNoContent());mvc.perform(delete("/api/v1/categories/"+c.getId())).andExpect(status().isNoContent());}
 @Test @WithMockUser(roles="ADMIN") void favoritePreventsBookDeletionAndHistoryIsKept()throws Exception{var b=service.createBook(request());var u=users.save(User.builder().email("rubric@test.com").fullName("Test").password("unused").build());favorites.save(Favorite.builder().user(u).book(b).build());mvc.perform(delete("/api/v1/books/"+b.getId())).andExpect(status().isConflict());assertTrue(books.existsById(b.getId()));assertEquals(2,copies.countByBookId(b.getId()));}
 @Test @WithMockUser(roles="USER") void readerCannotDeleteBooks()throws Exception{var b=books.save(Book.builder().title("Reader test").totalQuantity(0).availableQuantity(0).rentalPrice(BigDecimal.ZERO).salePrice(BigDecimal.ZERO).status(BookStatus.OUT_OF_STOCK).build());mvc.perform(delete("/api/v1/books/"+b.getId())).andExpect(status().isForbidden());assertTrue(books.existsById(b.getId()));}
 @Test @WithMockUser(roles="ADMIN") void invalidRelationIsRejectedWithoutCreatingHalfBook(){var r=request();r.setCategoryId(999999L);assertThrows(com.example.library.exception.ResourceNotFoundException.class,()->service.createBook(r));assertEquals(0,books.count());}
 @Test @WithMockUser(roles="ADMIN") void invalidBookFieldsAreRejected()throws Exception{mvc.perform(post("/api/v1/books").contentType(MediaType.APPLICATION_JSON).content("{\"title\":\"Bad\",\"totalQuantity\":2000,\"rentalPrice\":-1,\"salePrice\":1,\"coverImageUrl\":\"javascript:alert(1)\"}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.fields.totalQuantity").exists());assertEquals(0,books.count());}
 @Test void forgedJwtCannotAuthenticate()throws Exception{mvc.perform(get("/api/v1/profile").header("Authorization","Bearer eyJhbGciOiJIUzI1NiJ9.e30.invalid")).andExpect(status().isUnauthorized());}
 @Test void securityHeadersAndH2ConsoleAreProtected()throws Exception{mvc.perform(get("/api/v1/books")).andExpect(status().isOk()).andExpect(header().string("X-Frame-Options","DENY")).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(header().exists("Content-Security-Policy"));mvc.perform(get("/h2-console/")).andExpect(status().is4xxClientError());}
 @Test void sqlInjectionPasswordCannotLogin()throws Exception{mvc.perform(post("/api/v1/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"nobody@example.com\",\"password\":\"' OR 1=1 --\"}")).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.token").doesNotExist());}
 @Test void registerCannotGrantAdminRole()throws Exception{mvc.perform(post("/api/v1/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"newrubric@example.com\",\"password\":\"test-password-123\",\"fullName\":\"New user\",\"roles\":[\"ROLE_ADMIN\"]}")).andExpect(status().isOk()).andExpect(jsonPath("$.roles[0].name").value("ROLE_USER")).andExpect(jsonPath("$.password").doesNotExist());}
 @Test void catalogPaginatesManyRecordsAndClampsLastPage()throws Exception{for(int i=0;i<85;i++)books.save(Book.builder().title("Large "+i).totalQuantity(1).availableQuantity(1).rentalPrice(BigDecimal.valueOf(i)).salePrice(BigDecimal.ONE).status(BookStatus.AVAILABLE).build());mvc.perform(get("/api/v1/books/catalog").param("q","Large")).andExpect(status().isOk()).andExpect(jsonPath("$.totalElements").value(85)).andExpect(jsonPath("$.content.length()").value(12));mvc.perform(get("/api/v1/books/catalog").param("q","Large").param("page","999")).andExpect(status().isOk()).andExpect(jsonPath("$.number").value(7)).andExpect(jsonPath("$.content.length()").value(1));}
 @Autowired LoanRepository loanRepository;
 @Test @WithMockUser(roles="ADMIN") void newestLoansAreFirstAndSameDayUsesDescendingId()throws Exception{var user=users.save(User.builder().email("sort@test.com").fullName("Sort user").password("unused").build());var older=loanRepository.save(Loan.builder().user(user).borrowDate(java.time.LocalDate.of(2026,11,5)).dueDate(java.time.LocalDate.of(2026,11,19)).rentalFee(BigDecimal.ZERO).status(LoanStatus.BORROWED).build());var today=loanRepository.save(Loan.builder().user(user).borrowDate(java.time.LocalDate.of(2026,11,6)).dueDate(java.time.LocalDate.of(2026,11,20)).rentalFee(BigDecimal.ZERO).status(LoanStatus.BORROWED).build());var latest=loanRepository.save(Loan.builder().user(user).borrowDate(java.time.LocalDate.of(2026,11,6)).dueDate(java.time.LocalDate.of(2026,11,20)).rentalFee(BigDecimal.ZERO).status(LoanStatus.BORROWED).build());mvc.perform(get("/api/v1/loans")).andExpect(status().isOk()).andExpect(jsonPath("$[0].id").value(latest.getId())).andExpect(jsonPath("$[1].id").value(today.getId())).andExpect(jsonPath("$[2].id").value(older.getId()));}
}
